import{z as s,x as p,o as t,c as d,q as o,j as i,D as n,d as E,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"Qwen2.5-VL 报告","description":"","frontmatter":{"title":"Qwen2.5-VL 报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen25-vl-paper.md","filePath":"llm/qwen25-vl-paper.md","lastUpdated":1791063341000}'),A={name:"llm/qwen25-vl-paper.md"};function m(h,a,T,L,c,V){const r=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="qwen2-5-vl-报告" tabindex="-1">Qwen2.5-VL 报告 <a class="header-anchor" href="#qwen2-5-vl-报告" aria-label="Permalink to &quot;Qwen2.5-VL 报告&quot;">​</a></h1><div class="epigraph"><p>从零训原生动态分辨率 ViT，窗口注意力压视觉计算；时间维用动态帧率与绝对时间对齐的 MRoPE，让小时级视频能按秒定位。</p><footer>—— Qwen Team，Qwen2.5-VL Technical Report，arXiv:2502.13923</footer></div><p>通义 2025 年 1 月放出的 Qwen2.5-VL 是视觉–语言旗舰的一代技术报告，而不是又一次「把 CLIP 接到聊天模型」的配方复述。开源 <strong>3B / 7B / 72B</strong> 的 Base 与 Instruct，语言模型从 Qwen2.5 初始化。相对 Qwen2-VL（Wang 等，arXiv:2409.12191），原文列出四条差分：ViT 里的窗口注意力、时间维动态 FPS、把 MRoPE 的时间分量对齐到<strong>绝对时间</strong>、预训练从约 1.2T 扩到约 <strong>4.1T</strong>。窗口层与 <a href="/llm/qwen-vl-patch-merge">2×2 merge</a>、<a href="/llm/qwen-vl-naive-dynamic-res">原生切块</a> 已有专文；本篇按报告本身写架构表、数据课程与定位/文档/智能体，不把 Qwen3-VL 的 SigLIP-2 与 DeepStack 倒填进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>当时开源 VLM 的通病是「什么都会一点、细粒度都不够」。高清文档让 ViT 内部仍是二次注意力，训练步时间被最大图钉死；视频把时间 ID 绑在帧号上，同一段 10 秒可以是 10 帧也可以是 100 帧，模型分不清播放速度；相对坐标把框归一化到 \\([0,1]\\)，发票上的章和缩略图里的章在数值上可以一样大。文档若拆给版面、OCR、图表多个专家，通用模型只能做看图说话；手机与桌面点击若没有统一动作空间，多步轨迹无法当成函数调用学。</p><p>报告要在<strong>不推翻动态分辨率</strong>的前提下，把空间尺度、时间尺度、结构化文档和 GUI 动作收进同一套生成目标。旗舰 72B 被写成接近当时 GPT-4o / Claude 3.5 Sonnet 的文档与图表档，3B/7B 是边侧档，数字不可混用。</p><h3 id="时间-id-不应等于帧号" tabindex="-1">时间 ID 不应等于帧号 <a class="header-anchor" href="#时间-id-不应等于帧号" aria-label="Permalink to &quot;时间 ID 不应等于帧号&quot;">​</a></h3><p>Qwen2-VL 的 MRoPE 把位置拆成时间 / 高 / 宽。文本三分量相同，退回 1D RoPE；静态图时间分量恒定；视频则按帧递增时间 ID。2.5-VL 指出：这把时间绑在采样帧数上，同一真实时长在不同 FPS 下相位不同。要对齐的是<strong>绝对时间间隔</strong>，而不是帧下标。动态 FPS 采样把「一秒里来几帧」变成训练分布，而不是推理时的固定超参。</p><p><span class="marginnote">直觉类比：帧号像书页码——同一本书，精装版 200 页、口袋版 300 页，「第 50 页」的位置完全不同；绝对时间像目录里的「第 3 章」，换个版本照样找得到。模型要记住的是后者。</span></p><p><span class="marginnote">3B/7B/72B 共用同一 32 层 ViT（隐维 1280、16 头、patch 14、窗口 112），全注意力层号 \\(\\{7,15,23,31\\}\\)。变的是 LLM 宽度与 merger 输出维（2048 / 3584 / 8192）。不要为 3B 另编一套视觉骨干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>视觉编码器从零训练：CLIP 预训练 → 视觉–语言对齐 → 端到端。结构向 LLM 靠拢：RMSNorm、SwiGLU、二维 RoPE。多数层窗口注意力（最大 \\(112\\times 112\\) 像素 = \\(8\\times 8\\) patch），小于窗口的区域不补零；只有四层全图注意力。图在送入 ViT 前把高宽收成 28 的倍数，patch 步长 14。视频把连续两帧打成一个 3D patch，降低送进语言模型的 token 数。Merger 仍是相邻四 patch 拼接再两层 MLP，与 Qwen2.5 隐维对齐。</p><p>实现侧的空间策略延续动态分辨率，但框与点坐标直接使用输入图像的真实宽高、不做归一化；时间侧训练期动态采样帧率，MRoPE 的时间分量按时间戳对齐以编码事件节奏。长视频另合成超过半小时的多帧字幕，时间戳监督同时提供秒与时分秒帧两种写法。</p><h3 id="文档-html、绝对框与-gui-函数调用" tabindex="-1">文档 HTML、绝对框与 GUI 函数调用 <a class="header-anchor" href="#文档-html、绝对框与-gui-函数调用" aria-label="Permalink to &quot;文档 HTML、绝对框与 GUI 函数调用&quot;">​</a></h3><p>传统流水线拆成版面分析、OCR、图表、插图多个模型。2.5-VL 把表格、图表、公式、自然图、乐谱、化学式统一写成 HTML：段落、表、图都带 <code>data-bbox=&quot;x1 y1 x2 y2&quot;</code>，图表在 <code>div.chart</code> 里同时放图和表内容，公式 / 乐谱 / SMILES 各有 class。读序按典型阅读顺序排。这样版式与文字是同一个生成目标。OCR 数据含合成野外文字、开源与内部真实图，并扩法德意西葡阿俄日韩越等；图表用 matplotlib / seaborn / plotly 合成约 100 万；表格用离线识别模型处理约 600 万真实表。</p><p>智能体：手机 / Web / 桌面截屏上合成 caption 与 UI grounding；动作空间统一成函数调用。多步轨迹来自开源与虚拟环境，每步用前后截屏加全局目标写推理过程，模型过滤低质思维，避免只拟合标准点击。</p><p>预训练三阶段：视觉预训练约 1.5T（只训 ViT，8K，caption / 知识 / OCR）；多模态预训练约 2T（ViT+LLM，交错图文、VQA、视频、grounding、agent）；长上下文约 0.6T、序列 32K（长视频、长文档、长 agent）。合计约 4.1T。交错图文用四维打分：纯文本质量、图文相关、信息互补、密度平衡。</p>',17)),(t(),i(B,null,{default:n(()=>[l(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%8E%9F%E7%94%9F%E5%88%86%E8%BE%A8%E7%8E%87%E5%9B%BE%22%5D%20--%3E%20ViT%5B%22%E4%BB%8E%E9%9B%B6%20ViT%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%B1%82%20%2B%20%E5%9B%9B%E5%B1%82%E5%85%A8%E5%9B%BE%22%5D%0A%20%20VID%5B%22%E5%8A%A8%E6%80%81%20FPS%20%E8%A7%86%E9%A2%91%22%5D%20--%3E%20ViT%0A%20%20ViT%20--%3E%20MER%5B%222x2%20MLP%20merger%22%5D%0A%20%20MER%20--%3E%20LLM%5B%22Qwen2.5%20%2B%20%E7%BB%9D%E5%AF%B9%E6%97%B6%E9%97%B4%20MRoPE%22%5D%0A%20%20BOX%5B%22%E7%BB%9D%E5%AF%B9%E5%83%8F%E7%B4%A0%E6%A1%86%20%2F%20%E7%82%B9%22%5D%20--%3E%20LLM%0A%20%20HTML%5B%22QwenVL-HTML%20%E6%96%87%E6%A1%A3%22%5D%20--%3E%20LLM%0A%20%20GUI%5B%22%E7%BB%9F%E4%B8%80%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%20GUI%22%5D%20--%3E%20LLM%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"开放词汇检测扩到一万以上物体类，并合成「查询里根本没有的类」与多实例图，逼模型学会说「没有」而不是乱框。指向数据含 PixMo 公开集与内部合成，格式覆盖 XML / JSON / 自定义，不要假设线上只出一种 schema。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"论文把绝对坐标的动机讲成「让尺度可学习」：同一物体在 4K 原图与缩略图上的框数值本不相同，模型因此必须把「占多少像素」与语义绑定——对计数、指向、开放词汇检测是显式监督，而相对坐标恰好抹掉这层信息。时间维同理：时间 ID 差分正比真实秒差，不同帧率的视频在时间轴上可对齐。",-1)),(t(),i(B,null,{default:n(()=>[l(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22%E8%A7%86%E9%A2%91%20A%EF%BC%9A10%20%E7%A7%92%2010%20%E5%B8%A7%EF%BC%881%20FPS%EF%BC%89%22%5D%20--%3E%20T1%5B%22%E5%B8%A7%E5%8F%B7%200%20%E5%88%B0%209%EF%BC%8C%E6%97%B6%E9%97%B4%E6%88%B3%200%20%E5%88%B0%2010%20%E7%A7%92%22%5D%0A%20%20V2%5B%22%E8%A7%86%E9%A2%91%20B%EF%BC%9A10%20%E7%A7%92%20100%20%E5%B8%A7%EF%BC%8810%20FPS%EF%BC%89%22%5D%20--%3E%20T2%5B%22%E5%B8%A7%E5%8F%B7%200%20%E5%88%B0%2099%EF%BC%8C%E6%97%B6%E9%97%B4%E6%88%B3%200%20%E5%88%B0%2010%20%E7%A7%92%22%5D%0A%20%20T1%20--%3E%20M%5B%22MRoPE%20%E6%97%B6%E9%97%B4%E5%88%86%E9%87%8F%E6%8C%89%E7%A7%92%E5%AF%B9%E9%BD%90%22%5D%0A%20%20T2%20--%3E%20M%0A%20%20M%20--%3E%20Q%5B%22%E4%B8%A4%E6%AE%B5%E8%A7%86%E9%A2%91%E6%97%B6%E9%97%B4%E5%87%A0%E4%BD%95%E4%B8%80%E8%87%B4%22%5D%0A%20%20Q%20--%3E%20LOC%5B%22%E3%80%8C%E7%AC%AC%207%20%E7%A7%92%E3%80%8D%E5%8F%AF%E7%9B%B4%E6%8E%A5%E6%8C%87%E5%88%B0%E5%AF%B9%E5%BA%94%E5%B8%A7%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：两帧一组的 3D patch 让视频 token 直接减半——一段 \\(100\\) 帧、每帧约 \\(400\\) 个 token 的视频，从约 \\(40000\\) 个降到约 \\(20000\\) 个，上下文压力少一半，而 FPS 仍由采样策略另定。</span></p><p>窗口注意力把 ViT 的二次项压成近似线性：高清发票不再因为「最大边」而把整步训练拖死。四层全图注意力保留跨窗口的版面关系，所以不是纯局部卷积的替代品。HTML 监督迫使解码器维护嵌套与框，而不是只吐纯文本。智能体的逐步推理文本把「点哪里」和「为什么点」拆开，降低对标注轨迹的过拟合。</p><h3 id="三阶段冻结谁在学" tabindex="-1">三阶段冻结谁在学 <a class="header-anchor" href="#三阶段冻结谁在学" aria-label="Permalink to &quot;三阶段冻结谁在学&quot;">​</a></h3><p>第一阶段不动 LLM，避免随机 ViT 把语言能力冲掉；第二阶段才把视觉与语言绑在一起；长上下文阶段才把 32K 文档和长视频放进来。这解释报告反复强调「保持 Qwen2.5 的语言能力」：多模态加量不是用图把文本挤出记忆。72B 在文档与图表上的表接近当时闭源旗舰，是数据与分辨率策略的结果，不是换了一套注意力公式。</p><p><span class="marginnote">评定位至少看框和点两套格式；评视频至少看描述与时间定位。只报通用 VQA 会选出「会看物体、不会读表、不会对秒」的检查点。MMMU、MathVista、DocVQA、OCRBench 要分列，不要合成一个「接近 GPT-4o」的口号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>视觉 token 仍占上下文：小时视频必须靠 FPS 与 merge 降长度，不是「窗口注意力自动支持任意时长」。绝对坐标依赖预处理把图缩放到训练时同一套像素预算；应用侧若先把图缩到 224 再问「原图像素框」，对不上。乐谱 ABC、化学 SMILES 在 HTML schema 里出现，生产准确率要单测。GUI 智能体的动作空间是训练时的函数集，未见过的 OS 控件会退化成乱点。</p><p><span class="marginnote">常见误区：以为窗口注意力让模型「自动支持任意长的视频」。窗口注意力省的是 ViT 内部计算，不省上下文窗口——小时级视频仍要压 FPS、靠 merge 减 token，两头都要管。</span></p><p>Qwen3-VL 的 <a href="/llm/qwen3-vl-siglip2">SigLIP-2</a> 与 <a href="/llm/qwen3-vl-deepstack">DeepStack</a> 是下一代差分，不能回写进 2.5-VL。开源权重与云上 Qwen-VL-OCR 产品模板不是同一契约。3B 开 embedding tying，7B/72B 不开，部署时不要用同一套量化脚本硬套。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen2.5-VL 用从零训练的动态分辨率 ViT、约 4.1T 多模态预训练，开源 3B/7B/72B。</li><li>原文四条增量：窗口化 ViT、动态 FPS、绝对时间 MRoPE、数据从 1.2T 扩到 4.1T；绝对像素坐标、统一 HTML 文档、GUI 函数调用写在能力层。</li><li>空间切块与 2×2 merge 继承 Qwen2-VL，细节见已有专文。</li><li>出处：Qwen Team，<em>Qwen2.5-VL Technical Report</em>，arXiv:2502.13923，2025。对照博客 <em>Qwen2.5 VL</em>（2025-01）与 Wang 等 Qwen2-VL，arXiv:2409.12191。</li></ul>',11))])}const P=s(A,[["render",m]]);export{M as __pageData,P as default};
